\centering
\small
\caption{SmolVLA pruning ablation on LIBERO-Object. All configurations collapse to 0\% SR. The official checkpoint (59.2\% baseline) shows the same cliff-edge.}
\label{tab:smolvla_ablation}
\begin{tabular}{llccrr}
\toprule
Scoring & $k$ & Mechanism & SR (\%) & Episodes & Wilson 95\% CI \\
\midrule
\multicolumn{2}{l}{\textit{Baseline (bypass)}} & -- & 44.8 & 500 & [40.5, 49.2] \\
\midrule
